<main class="section"><div class="admin-page-intro"><div><span class="eyebrow">Angebotsstruktur</span><h1>Kategorien</h1><p>Lege fest, welche Artikel- und Digitalbereiche für Angebote verfügbar sind.</p></div><a class="btn ghost" href="/admin">Zur Übersicht</a></div><section class="card admin-form"><h2>Kategorie speichern</h2><p class="muted">Neue Kategorien stehen anschließend im Angebotseditor zur Auswahl.</p><form method="post" class="form-grid"><?=App\Core\Csrf::field()?><label class="full">Name<input name="name" required></label><label>Übergeordnete Kategorie<select name="parent_id"><option value="">Keine übergeordnete Kategorie</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=App\Core\View::e($c['name'])?></option><?php endforeach;?></select></label><label>Sortierung<input name="sort_order" type="number" value="0"></label><label>Symbol (optional)<input name="icon" placeholder="z. B. socken"></label><label class="check"><input type="checkbox" name="is_digital" value="1"> Digitale Kategorie</label><button class="btn primary full">Kategorie anlegen</button></form></section><div class="table-wrap"><table><thead><tr><th>Name</th><th>Typ</th><th>Status</th><th>Angebote</th><th>Aktion</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><strong><?=App\Core\View::e($c['name'])?></strong><?php if($c['parent_name']):?><small>Unterkategorie von <?=App\Core\View::e($c['parent_name'])?></small><?php endif;?></td><td><?=$c['is_digital']?'digital':'physisch'?></td><td><?=$c['is_active']?'aktiv':'deaktiviert'?></td><td><?= (int)$c['offer_count'] ?></td><td class="row-actions"><a class="btn" href="/admin/kategorien/<?=$c['id']?>">Bearbeiten</a><form method="post" action="/admin/kategorien/<?=$c['id']?>/duplizieren"><?=App\Core\Csrf::field()?><button class="btn">Duplizieren</button></form><?php if(!$c['is_system_template'] && (int)$c['offer_count']===0):?><form method="post" action="/admin/kategorien/<?=$c['id']?>/loeschen"><?=App\Core\Csrf::field()?><button class="btn" data-confirm="Kategorie wirklich löschen?">Löschen</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></main>